/* Canvas art, story presentation and input. All artwork is drawn on the pixel grid. */
(()=>{
  'use strict';
  const Art=window.CityArt,E=window.SZ,D=window.CityWorld,canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),overlay=document.getElementById('overlay'),audio=new window.CityAudio();
  let battleGroup='speak';
  let storyShown=null;
  let state=E.fresh(),route=[],routeTarget=null,lastMove=0,lastRoute=0,lastNearby='',frame=0,heldTimer=null;
  const motion=new window.CityMotion.Motion(E,()=>state,()=>{nearby();hud();});
  const $=id=>document.getElementById(id),money=n=>'€'+(n/100).toFixed(2),clock=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
  const C={pavement:'#b5b494',tile:'#a7aa8a',road:'#64766b',roadEdge:'#455e54',dark:'#29483f',ink:'#183b33',cream:'#e7d7ae',amber:'#e9af61',green:'#bdcf96',red:'#b2694d',peach:'#c79a70',roof:'#7c8770',shadow:'#526954'};
  const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}
  function text(s,x,y,color=C.cream,size=8,align='left'){ctx.fillStyle=color;ctx.font=`bold ${size}px monospace`;ctx.textAlign=align;ctx.fillText(s,Math.round(x),Math.round(y));ctx.textAlign='left';}
  function line(speaker,line){$('speaker').textContent=speaker;$('line').textContent=line;$('speaker-icon').textContent=speaker[0];}
  function hud(){
    const memory=E.Memories.current(state);document.body.dataset.memory=String(!!memory);
    document.querySelector('.district small').textContent=memory?'MEMORIES':state.room==='train'?'LINE 1':state.room?.startsWith('victoria')?'VICTORIA':'KATO PATISIA';
    document.body.dataset.mode=state.mode;$('action-label').textContent=state.mode==='explore'?(E.nearest(state)?.id==='continue-memory'?'NEXT':E.nearest(state)?.id==='exit'?'EXIT':!state.room&&E.Rooms.rooms[E.nearest(state)?.id]?'ENTER':E.nearest(state)?'TALK':'LOOK'):'OK';for(const id of ['journal','phone','map'])$(id).disabled=(['intro','battle','ending','cutscene','memory-battle'].includes(state.mode)||(E.Opening.current(state)&&E.Opening.current(state).kind!=='explore'))||(id==='phone'&&!!memory)||(id==='map'&&!!state.room);$('location-tag').textContent=state.room?E.Rooms.rooms[state.room].name:D.area(state.x,state.y);$('map').hidden=!!state.room;canvas.setAttribute('aria-label',memory?E.Rooms.rooms[state.room].name+'. Walk or tap to approach. A interacts. B opens the memory journal.':state.room?E.Rooms.rooms[state.room].name+'. Walk with the joystick or tap a person or object to approach. A interacts. B walks to the exit.':'Kato Patisia neighborhood. Walk with the joystick; tap a person or doorway to approach. A interacts.');Art.minimap($('mini-map').getContext('2d'),state);
    $('clock').textContent=memory?memory.age:clock(state.minutes);$('money').textContent=memory?'YOU':money(state.money);document.querySelector('.pocket small').textContent=memory?'PLAYING AS':'POCKET';$('energy').textContent=state.energy+' / 100';$('stress').textContent=state.stress+' / 100';$('energy-meter').style.width=state.energy+'%';$('stress-meter').style.width=state.stress+'%';
    const quests=memory?E.Memories.allPlaces(memory).filter(p=>memory.required.includes(p.id)).map(p=>({done:!!state.memory.visited[memory.id+':'+p.id],name:p.name,sub:E.Memories.goal(state)})):[{done:state.flags.wages||state.flags.walkedAway,name:'Chase the missing wages',sub:state.flags.settlement?'€12 recovered · €12 unresolved':state.flags.wages?'€24 recovered':state.flags.walkedAway?'You chose to walk away':'The stockroom owes you €24.'},{done:state.flags.delivered,name:'Bring groceries home',sub:state.flags.delivered?'Eleni is making dinner.':state.inventory.groceries?'Bag packed. Eleni is at home.':'Market → home. Budget: €4.20.'},{done:state.flags.attended,name:'Make it to the basement gig',sub:state.flags.attended?'You made room for the music.':'Dimos is playing at 19:00.'}];
    $('quests').replaceChildren(...quests.map(q=>{const li=document.createElement('li');li.className=q.done?'done':'';const mark=document.createElement('span');mark.textContent=q.done?'✓':'';const content=document.createElement('div');content.textContent=q.name;const small=document.createElement('small');small.textContent=q.sub;content.append(small);li.append(mark,content);return li;}));$('quest-count').textContent=quests.filter(q=>q.done).length+' / '+quests.length;
  }
  function close(){if(state.mode==='intro'||state.mode==='ending'||state.mode==='battle')return;state.mode='explore';overlay.className='overlay';overlay.replaceChildren();$('location-tag').hidden=false;canvas.focus({preventScroll:true});hud();nearby();if(E.Memories.current(state))line('NEXT',E.Memories.goal(state));}
  function panel({kicker,title,body,options=[],className='',note='',mode='dialogue',extra,portrait}){
    releaseInput();motion.sync();typing=null;route=[];routeTarget=null;state.mode=mode;overlay.className='overlay open';overlay.replaceChildren();$('location-tag').hidden=true;
    const p=document.createElement('section');p.className='scene-panel '+className;p.setAttribute('role','dialog');p.setAttribute('aria-modal','true');p.setAttribute('aria-label',title);
    const kick=document.createElement('div');kick.className='eyebrow';kick.textContent=kicker;
    const heading=document.createElement('h2');heading.textContent=title;const header=document.createElement('div');header.className='dialogue-head';const who=portrait||E.Memories.current(state)?.avatar||(/mina/i.test(kicker+' '+title)?'mina':/eleni/i.test(kicker+' '+title)?'eleni':/dimos/i.test(kicker+' '+title)?'dimos':/supervisor|stockroom/i.test(kicker+' '+title)?'boss':'aris');header.append(Art.avatar(who));const headingText=document.createElement('div');headingText.append(kick,heading);header.append(headingText);p.append(header);
    if(body){const b=document.createElement('p');b.setAttribute('aria-label',body);b.textContent=reduceMotion?body:'';p.append(b);if(!reduceMotion)typing={node:b,text:body,shown:0};}if(extra)extra(p);
    if(note){const n=document.createElement('p');n.className='scene-note';n.textContent=note;p.append(n);}
    const choices=document.createElement('div');choices.className='choice-list';for(const [i,o] of options.entries()){const b=document.createElement('button');b.className='choice';b.disabled=!!o.disabled;b.dataset.choice=String(i);const label=document.createElement('span');label.textContent=o.label;b.append(label);if(o.hint){const h=document.createElement('small');h.textContent=o.hint;b.append(h);}b.addEventListener('click',()=>{finishTyping();audio.effect('choice');o.run();hud();});choices.append(b);}p.append(choices);overlay.append(p);hud();requestAnimationFrame(()=>choices.querySelector('button:not(:disabled)')?.focus({preventScroll:true}));
  }
  function response(title,body,portrait){panel({portrait,className:'speech-panel',kicker:'',title,body,options:[{label:'Continue',hint:'A',run:close}]});line(title,body);}
  function intro(){panel({portrait:'memory-child',kicker:'STEREOTYPE ZERO / PLAYABLE STORY PREVIEW',title:'A life before Aris.',body:'Begin with playable chapters: childhood, the Deers, summer camp, school, December 2008, TEI and a shared home. Then take control of Aris and choose your own evening.',note:'These short scenes are adaptations inspired by the narrated life, not exact recollections or the full biography. Character appearances are provisional. You begin as the child. Existing saves can still continue.',className:'intro-panel',mode:'intro',options:[{label:'Begin the memories',hint:'New story · explore the years before Aris',run:()=>{E.startMemories(state);motion.sync();Art.resetCamera();memoryCard();}},{label:'Continue a saved evening',hint:'Local save',disabled:!hasSave(),run:load}]});}
  function memoryCard(){const q=E.Memories.current(state);panel({kicker:'MEMORY '+(E.Memories.scenes.indexOf(q)+1)+' / '+E.Memories.scenes.length+' · '+q.age,title:q.name,body:q.intro,note:q.goal+' These are adapted scenes for testing the introduction.',portrait:q.avatar,options:[{label:'Walk into the memory',hint:'Joystick to walk · A to interact',run:()=>{close();line('YOU',E.Memories.goal(state));}}]});}
  function memoryInteraction(p){
    const q=E.Memories.current(state);
    if(q.id==='courtyard'&&p.id==='indoor-play'){
      if(E.Opening.current(state)?.id!=='explore-home')return response('Omiros',E.Memories.goal(state),'family-brother');
      return panel({className:'speech-panel',extra:playStage,kicker:'',title:'Omiros',portrait:'family-brother',body:'“Pass it here! It’s my turn.”',options:[{label:'Roll the ball to Omiros',run:()=>{state.mode='explore';if(E.storyAction(state,'play-inside')){storyShown=null;save(false);driveOpening(0);}}},{label:'Explore a little longer',run:close}]});
    }
    if(q.id==='courtyard'&&p.id==='mother'&&E.Opening.current(state)?.id==='tell-mum'){if(E.storyAction(state,'report-sky')){storyShown=null;save(false);driveOpening(0);}return;}
    if(p.id==='family-album')return familyBook();
    if(p.id==='ball')return childhoodPlay();
    const item=E.Memories.items[p.id];
    if(p.id==='memory-notebook'){state.mode='explore';E.memoryAct(state,p.id,'write');return notebook();}
    if(item?.encounter){const result=E.beginMemoryEncounter(state,item.encounter);if(!result.ok)return response(p.name,result.text||'Walk a little closer.');save(false);return memoryEncounter();}
    if(item)return panel({className:'speech-panel',kicker:'',title:item.speaker||p.name,body:item.body,portrait:p.who||q.avatar,options:item.choices.map((choice,i)=>({label:item.options[i],run:()=>{state.mode='explore';const result=E.memoryAct(state,p.id,choice);if(!result.ok){response(p.name,result.text||'Walk a little closer first.');return;}if(p.id==='station-memory'&&choice==='recall'&&!reduceMotion){$('world').classList.remove('memory-recall');requestAnimationFrame(()=>$('world').classList.add('memory-recall'));}if(['father','child-records','guitar','records'].includes(p.id))audio.phrase('guitar');response(item.speaker||p.name,result.text,p.who||q.avatar);save(false);}})).concat([{label:'Leave it for now',run:close}])});
    if(p.id==='continue-memory'){
      if(!E.Memories.complete(state))return response('A little more time here',E.Memories.goal(state));
      const final=q.id==='shared-home';return panel({kicker:final?'THE HANDOVER / ARIS':'TIME PASSES',title:final?'Another evening. Another life.':q.id==='courtyard'?'Everyone accounted for.':'The city changes with you.',body:final?'The sound of the room gives way to the street. Aris is twenty-four. His shift ended, but his wages have not arrived. Eleni needs groceries; Dimos has kept a place for his demo. From here, his decisions are yours.':q.id==='courtyard'?'The bag is packed. The last bounce of the ball fades behind you. Mum checks that both of you are there; Dad closes the door. You and Omiros have one more story to tell on the way. Years later, the scout centre will become another place to belong.':'This preview jumps to another moment. The longer life story will connect these places through the years.',note:final?'You now leave the autobiographical role. Aris is the main character, with his own relationships and future.':'Your attention and choices are remembered. They do not rewrite the narrated life.',portrait:final?'aris':q.avatar,options:[{label:final?'Take control of Aris':'Continue to the next memory',run:()=>{state.mode='explore';if(!E.advanceMemory(state))return;motion.sync();Art.resetCamera();lastNearby='';$('world').classList.remove('scene-arrival');requestAnimationFrame(()=>$('world').classList.add('scene-arrival'));if(E.Memories.current(state))memoryCard();else{close();line('ARIS · INNER VOICE','Okay. Money first? Or check on Eleni?');toast('Now playing as Aris');save(false);}}},{label:'Stay a little longer',run:close}]});
    }
    const labels={ball:['Pass to Omiros','Try a shot against the wall'],brother:['Play together','Stop and listen'],kit:['Share the preparation','Check it with someone'],route:['Read the map together','Explain the route, then listen'],partner:['Listen before unpacking','Ask what to finish first'],books:['Find space on the shelf','Leave the larger box for tomorrow'],guitar:['Play a short phrase','Tune and play'],records:['Choose something to play','Remember a gig'],'scout-friend':['Sit and talk']};
    const ids=E.Memories.choices[p.id];if(!ids)return;
    panel({className:'speech-panel',kicker:'',title:p.speaker||p.name,body:p.id==='partner'?'“Can we leave the desk clear before opening another box?”':p.id==='brother'?'“Can I play too?”':p.id==='kit'?'The shared kit is laid out, ready to check.':'Take a moment here.',portrait:p.who||q.avatar,options:ids.map((choice,i)=>({label:labels[p.id][i],hint:state.memory.visited[q.id+':'+p.id]?'Revisit this moment':'',run:()=>{state.mode='explore';const result=E.memoryAct(state,p.id,choice);if(!result.ok)return;if(p.id==='ball')Art.memoryReact(choice);if(['guitar','records'].includes(p.id))audio.phrase('guitar');panel({className:'speech-panel',kicker:'',title:p.who?'Scene':p.name,body:result.text,portrait:p.who||q.avatar,options:[{label:'Continue',hint:'A',run:()=>{close();line('YOU',E.Memories.goal(state));save(false);}}]});}})).concat([{label:'Back to the memory',run:close}])});
  }
  function playStage(panel){const scene=document.createElement('canvas');scene.width=240;scene.height=86;scene.className='play-scene';scene.setAttribute('aria-label','You and Omiros playing with the ball');panel.append(scene);Art.playScene(scene.getContext('2d'),state,performance.now());}
  function childhoodPlay(){
    if(E.Opening.current(state)?.id!=='play-outside')return response('Omiros',E.Memories.goal(state),'family-brother');
    const a=state.memory.afternoon;if(a.finished)return panel({className:'speech-panel',kicker:'',title:'Omiros',portrait:'family-brother',body:'The ball comes to a stop between you. Omiros tilts his head upward.',options:[{label:'Look up',run:lookUp}]});
    const round=E.Memories.playRounds[a.round];panel({className:'speech-panel play-panel',extra:playStage,kicker:'COURTYARD / PLAY TOGETHER',title:'Keep the ball in play · '+a.round+'/3',portrait:'family-brother',body:round.cue,note:round.hint+' Three rallies together. You can retry or leave at any point.',options:[...['pass','steady','shot'].map((choice,i)=>({label:['Pass gently to Omiros','Steady the ball','Try the low wall'][i],run:()=>{state.mode='explore';const result=E.memoryPlay(state,choice);if(!result.ok)return close();Art.memoryReact(choice);panel({className:'speech-panel play-panel',extra:playStage,kicker:result.success?'RALLY KEPT':'TRY TOGETHER AGAIN',title:result.done?'Three rallies together.':result.success?'Back to you.':'Fetch it together.',portrait:'family-brother',body:result.text,options:[{label:result.done?'Look up':result.success?'Read the next moment':'Try this rally again',run:()=>{save(false);if(result.done)lookUp();else childhoodPlay();}},{label:'Pause the game',run:()=>{save(false);close();}}]});}})),{label:'Play later',run:close}]});
  }
  function lookUp(){state.mode='explore';if(E.storyAction(state,'look-up')){storyShown=null;save(false);driveOpening(0);}}
  function notebook(id){const life=state.memory.life,page=E.Life.pages[id];if(page&&life.pages[id])return panel({kicker:'MEMORY NOTEBOOK / '+page.source,title:page.title,body:page.text,mode:'journal',className:'notebook-panel',note:life.reflections[id]?'Later margin: this is one perspective. Other people can remember the same moment differently.':'',extra:p=>{for(const url of page.links){const a=document.createElement('a');a.textContent='Read the historical source';a.href=url;a.target='_self';a.rel='noopener';p.append(a);}},options:[{label:life.reflections[id]?'Margin added':'Add a later reflection',run:()=>{E.reflectMemory(state,id);save(false);notebook(id);}},{label:'Back to the notebook',run:notebook}]});
    panel({kicker:'MEMORY NOTEBOOK',title:'Things that stay with you',body:'Pages open through exploration. People remain people; the notebook holds what you noticed, not a score for knowing them.',mode:'journal',className:'notebook-panel',note:'Gathered kit: '+(Object.keys(life.bag).join(', ')||'Nothing yet.'),options:[...Object.keys(life.pages).map(id=>({label:E.Life.pages[id].title,hint:E.Life.pages[id].source,run:()=>notebook(id)})),{label:'Back to this moment',run:close}]});}
  function memoryEncounter(){const a=state.memory.life.active;if(!a)return close();const e=E.Life.encounters[a.id],won=a.result==='won',cue=won?'A way forward, together.':e.rounds[a.round][0];panel({kicker:a.id==='hyper'?'INNER VOICE / HYPER-EGO':'SOCIAL ENCOUNTER',title:e.name,body:a.log,portrait:a.id==='hyper'?E.Memories.current(state).avatar:e.who,mode:'memory-battle',className:'memory-encounter-panel',note:cue+' · Concerns answered '+a.round+'/3 · Focus '+a.focus+'/100. Focus does not force a decision.',extra:p=>{const c=document.createElement('canvas');c.width=240;c.height=86;c.className='life-encounter';c.setAttribute('aria-label','Your response shown between two characters');p.append(c);},options:won?[{label:'Keep this page and continue',run:()=>{E.finishMemoryEncounter(state);save(false);close();}}]:Object.entries(E.Life.moves).map(([id,m])=>({label:m.name,hint:m.hint,run:()=>{const result=E.memoryCommand(state,id);save(false);if(result.left)return close();memoryEncounter();}}))});}
  function drawMemoryEncounter(c,t){const a=state.memory.life.active;if(!a)return;const e=E.Life.encounters[a.id],q=E.Memories.current(state),w=c.canvas.width,h=c.canvas.height,p=Math.sin(t/220);c.fillStyle='#cbb992';c.fillRect(0,0,w,h);c.fillStyle='#a1af82';c.fillRect(0,h-22,w,22);Art.sprite(c,q.avatar,48+(a.result==='won'?2:0),h-9,'right',Math.abs(p)>.65?1:0,38);c.save();if(a.id==='hyper')c.globalAlpha=.45;Art.sprite(c,a.id==='hyper'?q.avatar:e.who,w-48,h-9,'left',a.round?2:0,38);c.restore();for(let i=0;i<3;i++){c.fillStyle=i<a.round?'#3b765e':'#eee4c9';c.fillRect(w/2-16+i*12,10,8,6);}if(a.turns){c.fillStyle=a.result==='won'?'#3b765e':'#b78148';const x=90+(Math.sin(t/350)+1)*25;c.fillRect(x,h-29,9,4);}}
  function driveOpening(dt){const before=E.Memories.current(state),b=E.Opening.current(state);if(!b){document.body.dataset.cinematic='false';return;}
    if(b.kind==='explore'){storyShown=null;document.body.dataset.cinematic='false';return;}
    document.body.dataset.cinematic='true';
    if(storyShown!==b.id){storyShown=b.id;releaseInput();pendingInteraction=null;motion.sync();Art.resetCamera();typing=null;overlay.replaceChildren();overlay.className='overlay';$('location-tag').hidden=true;
      if(b.kind==='dialogue'){panel({className:'speech-panel story-dialogue',kicker:'',title:b.speaker,body:b.text,portrait:b.who,options:[{label:'Continue',hint:'A',run:()=>{if(E.storyAdvance(state)){storyShown=null;motion.sync();Art.resetCamera();save(false);if(E.Opening.current(state)?.kind==='explore'){overlay.replaceChildren();overlay.className='overlay';hud();nearby();line('NEXT',E.Memories.goal(state));}else driveOpening(0);}}}]});}
      else state.mode='cutscene';
    }
    if(b.kind==='timed'&&!document.hidden&&E.storyUpdate(state,dt)){storyShown=null;motion.sync();Art.resetCamera();save(false);if(E.Memories.current(state)!==before){document.body.dataset.cinematic='false';memoryCard();}else driveOpening(0);}
  }
  function familyBook(){panel({kicker:'FAMILY / THE CHILDHOOD OPENING',title:'People around you.',portrait:'memory-child',mode:'journal',body:'Two sides of your family. Two people named Omiros.',extra:p=>{const list=document.createElement('dl');list.className='family-list';for(const member of E.Memories.family){const name=document.createElement('dt'),detail=document.createElement('dd');name.textContent=member.name;detail.textContent=member.relation;list.append(name,detail);}p.append(list);},note:'',options:[{label:'Back to the afternoon',run:close}]});}
  function hasSave(){try{return !!E.restore(localStorage.getItem('stereotype-zero-save'));}catch{return false;}}
  function transition(enter,id){releaseInput();pendingInteraction=null;if(enter?!E.enter(state,id):!E.exit(state))return;motion.sync();Art.resetCamera();lastNearby='';overlay.className='overlay';overlay.replaceChildren();hud();nearby();toast(state.room?E.Rooms.rooms[state.room].name:'Back in Kato Patisia');save(false);}
  function finishDoor(result){if(!result?.ok){if(result?.text)toast(result.text);return;}releaseInput();pendingInteraction=null;motion.sync();Art.resetCamera();lastNearby='';overlay.className='overlay';overlay.replaceChildren();hud();nearby();toast(state.room?E.Rooms.rooms[state.room].name:'Back in Kato Patisia');save(false);}
  function useDoor(p){if(state.x!==p.x||state.y!==p.y){motion.go(E.path(state,p,0),p);return;}state.facing=p.facing;finishDoor(E.crossDoor(state,p));}
  function social(who){return E.Rooms.topics[who].map(t=>({label:t.label,hint:state.topics[who+':'+t.id]?'Remember this conversation':'4 min · get to know them',run:()=>response(who==='eleni'?'Eleni':who==='mina'?'Mina':'Dimos',E.talk(state,who,t.id))}));}
  function inspect(title,text){response(title,text);}
  function interact(place){if(state.mode!=='explore')return;let p=place||E.nearest(state);if(!p){line('ARIS · INNER VOICE','Walk closer to a person or a marked place, then press A.');return;}if(motion.moving){pendingInteraction=p;motion.stop();return;}facePlace(p);audio.effect('choice');
    const doorway=E.doors(state).find(d=>d.id===p.id);if(doorway)return useDoor(doorway);
    if(E.Memories.current(state))return memoryInteraction(p);
    if(!state.room&&E.Rooms.rooms[p.id])return transition(true,p.id);
    if(state.room){
      if(E.Rooms.rooms[state.room].transit&&(p.id!=='exit'||state.room!=='metro'))return stationInteraction(p);
      if(p.id==='exit')return transition(false);
      if(p.id==='bed')return panel({kicker:'HOME / A SMALL PAUSE',title:'Your side of the room.',body:'Your headphones lie across the pillow. You can rest without ending the evening.',options:[{label:'Rest for fifteen minutes',hint:'+20 energy · −12 stress',run:()=>response('Home',E.home(state,'rest'))},{label:'Back to the room',run:close}]});
      if(p.id==='notebook')return inspect('Eleni’s notes','Bus tickets mark the pages of a university notebook. One sentence has been underlined twice: “Try again.” Ask her about it; the notebook cannot answer for her.');
      if(p.id==='dinner')return confirmEnd('home');
      if(p.id==='grocer')return shop('shop');
      if(p.id==='market-board')return inspect('The community board','A handwritten offer to swap textbooks sits beside a room wanted notice. Someone has crossed out a rent figure and written a larger one. These are fictional notices from this block.');
      if(p.id==='shift-board')return inspect('Thursday’s shift','Your name has been rubbed off the board. Mina’s dated photo still records the hours. If you need it, she is outside.');
      if(p.id==='soundcheck'){if(!state.topics['dimos:music'])return response('Dimos',E.talk(state,'dimos','music'));return inspect('A demo through one good channel','The first notes come back warmer through the borrowed speakers. Dimos adjusts a fader. “That’s it. Leave some space.” You can explore or stay for the set.');}
      if(p.id==='set')return confirmEnd('gig');
      p={...p,id:({eleni:'home',supervisor:'employer','dimos-inside':'dimos'})[p.id]||p.id};
    }

    if(p.id==='older-musician')return panel({kicker:'THE MUSICIAN / A PARALLEL LIFE',title:'A familiar face, another evening.',portrait:'memory-adult',body:E.memoryMeet(state),note:'This optional meeting is a fictional connection. Aris can continue his own evening.',options:[{label:'Ask about the records',run:()=>response('The musician','A record can bring a room full of people back to mind. You compare a few favourites; neither of you needs to agree on all of them.','memory-adult')},{label:'Listen to a few notes',run:()=>response('The musician','He plays a short phrase and leaves it unfinished. Dimos calls over from the mixer. There is still a set to get ready.','memory-adult')},{label:'Enjoy the evening',run:close}]});
    if(p.id==='home')panel({kicker:'HOME / ELENI, YOUR SISTER',title:'“Did you eat anything?”',body:state.flags.delivered?'The little kitchen smells of tomatoes. Eleni has her notes spread across the table.':'Eleni looks up from her notes. “There’s coffee. Not much else. How was the shift?”',options:[{label:state.flags.wages?(state.flags.settlement?'“Got half the money. I’m tired.”':'“They finally paid.”'):'“They still haven’t paid for Thursday.”',hint:'+ trust · 5 min',disabled:state.flags.homeTalk,run:()=>response('Eleni',E.home(state,'talk'))},{label:'Put the groceries on the table',hint:'5 min · + trust',disabled:!state.inventory.groceries||state.flags.delivered,run:()=>response('Eleni',E.home(state,'deliver'))},...social('eleni'),{label:'“I’ll be back.”',run:close}]});
    if(p.id==='kiosk')shop('kiosk');
    if(p.id==='shop')shop('shop');
    if(p.id==='mina'){if(state.flags.minaTalk)return panel({kicker:'MINA / COWORKER',title:'A minute outside.',body:E.mina(state,'listen'),options:[...social('mina'),{label:'See you in a bit',run:close}]});panel({kicker:'MINA / COWORKER',title:'“They lost your hours too?”',body:'Mina is finishing a cigarette outside. Her phone has a photo of Thursday’s rota. “Before you go in—can I tell you what happened with my shifts?”',options:[{label:'“Yeah. I’ve got a minute.”',hint:'Rota + support · 6 min',run:()=>response('Mina',E.mina(state,'listen'))},{label:'“Just send me the photo, please.”',hint:'Rota · 6 min',run:()=>response('Mina',E.mina(state,'rush'))},{label:'“Let’s talk later.”',run:close}]});}
    if(p.id==='dimos'){if(state.flags.dimosTalk)return panel({kicker:'DIMOS / OLD FRIEND',title:'Between two songs.',body:E.dimos(state,'honest'),options:[...social('dimos'),{label:'Back to the room',run:close}]});panel({kicker:'DIMOS / OLD FRIEND',title:'“You brought the demo?”',body:'A cable hangs out of his backpack. “The mixer has one good channel. We’ll make it work. Are you coming tonight?”',options:[{label:'“I promise. Save me a place.”',hint:'+ trust · 6 min',run:()=>response('Dimos',E.dimos(state,'promise'))},{label:'“I want to. I can’t promise yet.”',hint:'−3 stress · 6 min',run:()=>response('Dimos',E.dimos(state,'honest'))},{label:'“One thing at a time.”',run:close}]});}
    if(p.id==='bench')panel({kicker:'BETWEEN TWO APARTMENT BLOCKS',title:'A little shade.',body:'Someone has left a plastic chair beside the tree. A radio upstairs is arguing with the traffic.',options:[{label:'Sit. Let the evening breathe.',hint:'+12 energy · −10 stress · 10 min',run:()=>{E.tick(state,10,12,-10);response('Aris','For ten minutes, nothing is asked of you.');}},{label:'Keep walking',run:close}]});
    if(p.id==='employer'){if(state.flags.wages||state.flags.walkedAway)return response('The stockroom',state.flags.walkedAway?'You chose to leave this argument behind tonight.':state.flags.settlement?'€12 arrived. The rest is still owed. It will need another conversation, another day.':'The transfer is in your account. The conversation is over.');panel({kicker:'STOCKROOM / THURSDAY’S WAGES',title:'“Next week, probably.”',body:'You worked the shift. The supervisor says accounts are closed. You can insist, bring evidence, lean on support, or leave.',note:'Read the next reply. Evidence counters stalling; boundaries counter blame; negotiation counters an offer. Your stress is not your worth.',options:[{label:'“I need to sort this out today.”',hint:'Begin encounter',run:()=>{E.beginBattle(state);battleGroup='speak';audio.setScene('battle');battle();}},{label:'Come back with a clearer head',run:close}]});}
    if(p.id==='bus')panel({kicker:'PATISION / BUS CORRIDOR',title:'The 608 passes.',body:'North toward Galatsi. South toward Akadimia and Zografou. A bus pulls away while someone is still searching their pockets.',note:'Bus travel opens in a future chapter. This is a story map, with no live arrivals or timetable.',options:[{label:'Read the Athens map',run:()=>map('Athens')},{label:'Keep walking',run:close}]});
    if(['north','south'].includes(p.id))panel({kicker:'PATISION / '+(p.id==='north'?'NORTH':'SOUTH'),title:p.id==='north'?'Toward Ano Patisia.':'Toward the centre.',body:p.id==='north'?'The road continues toward Ano Patisia. Beyond it are the northern neighborhoods, and another evening.':'Koliatsou gives way to the Amerikis corridor, then the streets toward Victoria and Omonia. Tonight, you still have things to do here.',note:'The wider districts are future chapters.',options:[{label:'Read the Athens map',run:()=>map('Athens')},{label:'Back to the neighborhood',run:close}]});
    if(p.id==='venue')transition(true,'venue');
  }
  function shop(type){const kiosk=type==='kiosk';panel({kicker:kiosk?'THE KIOSK / UNDER THE STRIP LIGHT':'MARKET / THE LAST FEW THINGS',title:kiosk?'“The usual?”':'Dinner doesn’t have to be fancy.',body:kiosk?'A sesame bar, a ticket, a little light on the pavement. The kiosk owner is listening to the match.':'Bread, tomatoes, lentils. Enough for two. Someone behind you is counting coins too.',note:'Groceries and snacks use story prices. The urban ticket is €1.20 and activates at validation.',options:[...(!kiosk?[{label:'Buy the dinner groceries',hint:'€4.20 · 3 min',disabled:state.money<420||!!state.inventory.groceries||state.flags.delivered,run:()=>response('Market',E.buy(state,'groceries').text)}]:[]),{label:'Buy a sesame bar',hint:'€0.90 · 3 min',disabled:state.money<90,run:()=>response('Kiosk',E.buy(state,'snack').text)},...(kiosk?[{label:'Buy an urban ticket',hint:'€1.20 · 3 min',disabled:state.money<120||!!state.inventory.ticket,run:()=>response('Kiosk',E.buy(state,'ticket').text)}]:[]),{label:'“Thanks. See you.”',run:close}]});}
  function stationRefresh(){state.mode='explore';releaseInput();motion.sync();Art.resetCamera();pendingInteraction=null;lastNearby='';overlay.className='overlay';overlay.replaceChildren();$('location-tag').hidden=false;hud();nearby();save(false);}
  function stationAction(id){state.mode='explore';const result=E.transitAction(state,id);if(result.ok){stationRefresh();toast(result.text);}else response('At the gate',result.text);}
  function lineDiagram(){panel({kicker:'LINE 1 / FIRST PLAYABLE JOURNEY',title:'Kato Patisia ↔ Victoria',body:'Southbound: Kato Patisia → Agios Nikolaos → Attiki → Victoria. Northbound is the reverse.',note:'Victoria has a small playable square and a return journey. Intermediate stops are shown during travel; their districts are not yet playable. Journey time is compressed for this story.',extra:p=>{const line=document.createElement('div');line.className='rail-diagram';for(const [i,name]of E.LINE_STOPS.entries()){const stop=document.createElement('span');stop.textContent='● '+name;stop.className=i===0&&state.transit.station==='kato'||i===3&&state.transit.station==='victoria'?'current':'';line.append(stop);}p.append(line);},options:[{label:'Back to the station',run:close}]});}
  function stationInteraction(p){
    if(p.id==='ticket-machine')return panel({kicker:'ATHENS / URBAN TICKET',title:'One ticket, ninety minutes.',body:E.validTicket(state)?'Your validated ticket is still active until '+clock(state.transit.validUntil)+'.':'The clock starts when you validate at the gate, not when you buy the ticket.',note:'Urban fare: €1.20 / 90 minutes. Station layouts and journey timing are fictional.',options:[{label:'Buy one ticket',hint:'€1.20 · 3 min',disabled:state.money<120||!!state.inventory.ticket,run:()=>response('Ticket machine',E.buy(state,'ticket').text)},{label:'Back',run:close}]});
    if(p.id==='gate')return panel({kicker:'KATO PATISIA / TICKET GATES',title:'Touch the blue reader.',body:E.validTicket(state)?'Your ticket is active. The gate will open.':state.inventory.ticket?'Your unused ticket is ready. Validation starts ninety minutes.':'The reader stays red. Buy a ticket at the machine to the left.',options:[{label:'Validate and pass the gates',hint:E.validTicket(state)?'Active ticket · no new charge':'Use one ticket · 1 min',disabled:!E.validTicket(state)&&!state.inventory.ticket,run:()=>stationAction('gate')},{label:'Back to the hall',run:close}]});
    if(p.id==='board')return panel({kicker:'LINE 1 / BOARDING',title:state.transit.station==='kato'?'Toward Victoria.':'Back to Kato Patisia.',body:'The green-striped train opens its doors. Let people get off first; then step into the carriage.',note:'You can walk inside and talk to a passenger before continuing to your stop.',options:[{label:'Enter the train',run:()=>stationAction('board')},{label:'Read the line diagram',run:lineDiagram},{label:'Stay on the platform',run:close}]});
    if(p.id==='arrival'||p.id==='exit'){
      if(state.room==='train')return panel({kicker:'LINE 1 / JOURNEY',title:state.transit.ride?.to==='victoria'?'Next destination: Victoria':'Next destination: Kato Patisia',body:state.transit.ride?.to==='victoria'?'Agios Nikolaos. Attiki. The doors chime again; Victoria is next.':'Attiki. Agios Nikolaos. Familiar balconies appear beyond the windows.',note:'8 story minutes. You can stay in the carriage and talk before arriving.',options:[{label:'Travel and get off at your stop',hint:'8 min',run:()=>stationAction(p.id==='exit'?'exit':'arrive')},{label:'Stay in the carriage',run:close}]});
      return stationAction('exit');
    }
    if(p.id==='line-diagram')return lineDiagram();
    if(p.id==='staff'){state.mode='explore';const help=E.travelHelp(state);return response('Station attendant',help?'“Here. You need to get home.” The attendant gives you a return ticket. This assistance is a fictional game safeguard; it is not a promise about actual transport policy.':'“Buy a ticket, validate at the blue reader, then follow the Line 1 signs. Your ticket stays active for ninety minutes.”');}
    if(['commuter','rider','bookseller','square-friend'].includes(p.id))return response(({commuter:'Niki · after the shift',rider:'Panos · a fellow musician',bookseller:'Sofia · second-hand books','square-friend':'Lea · waiting for a friend'})[p.id],E.transitTalk(state,p.id));
  }
  function encounterScene(p){const scene=document.createElement('canvas');scene.width=300;scene.height=112;scene.className='encounter-scene';scene.setAttribute('aria-label','Aris and the supervisor react to your dialogue choices');p.append(scene);Art.encounter(scene.getContext('2d'),state,performance.now());}
  function playBattleAction(id){const before={pressure:state.battle.pressure,energy:state.energy,stress:state.stress};const result=E.act(state,id);if(!result.ok)return;const after={pressure:state.battle.pressure,energy:state.energy,stress:state.stress};Art.react(id,before,after);panel({kicker:'YOUR RESPONSE / '+E.ACTIONS[id].name.toUpperCase(),title:result.result==='won'?'The transfer arrives.':'Your words land.',className:'battle-panel battle-reaction',mode:'battle',extra:encounterScene,body:state.battle.log,note:'Objections '+before.pressure+' → '+after.pressure+' · Energy '+before.energy+' → '+after.energy+' · Stress '+before.stress+' → '+after.stress,options:[{label:result.result?'See the outcome':'Read the next reply',run:battle}]});}
  function battle(){const b=state.battle;if(b.result){audio.setScene('street');audio.effect('win');panel({kicker:'ENCOUNTER COMPLETE',title:b.result==='won'?'Paid. Finally.':b.result==='left'?'You kept your evening.':'Enough for tonight.',body:b.log,note:`${b.decisions} decisions · ${clock(state.minutes)} · Stress ${state.stress}/100`,mode:'battle',options:[{label:state.room?'Back to the stockroom':'Back to the street',run:()=>{E.finishBattle(state);overlay.className='overlay';$('location-tag').hidden=false;line('ARIS · INNER VOICE',b.log);canvas.focus({preventScroll:true});}}]});return;}
    const tell=E.tell(state),hint={stall:'He is delaying: “Accounts are closed.” Best reply: Show the rota.',blame:'He is blaming you: “You should have reminded me.” Best reply: Set a boundary.',offer:'He is offering half: “I can send part now.” Best reply for full wages: Negotiate.'}[tell];
    const group=battleGroup,ids=group==='speak'?['explain','evidence','boundary','negotiate']:group==='support'?['breathe','ally','snack']:['accept','leave'];
    panel({kicker:'WAGE DISPUTE / TURN '+(b.turn+1),title:'The unpaid shift',className:'battle-panel',mode:'battle',body:hint,extra:p=>{
      encounterScene(p);
      const stats=document.createElement('div');stats.className='encounter-stats';stats.textContent='Objections left '+b.pressure+'/68 · Energy '+state.energy+'/100 · Stress '+state.stress+'/100';p.append(stats);
      const meter=document.createElement('div');meter.className='battle-meter';meter.setAttribute('role','progressbar');meter.setAttribute('aria-label','Supervisor objections remaining; reach zero for full wages');meter.setAttribute('aria-valuenow',b.pressure);meter.setAttribute('aria-valuemin','0');meter.setAttribute('aria-valuemax','68');const fill=document.createElement('i');fill.style.width=b.pressure/68*100+'%';meter.append(fill);p.append(meter);
      const log=document.createElement('p');log.className='battle-log';log.textContent=b.log;p.append(log);
      const tabs=document.createElement('div');tabs.className='encounter-tabs';for(const [id,name]of [['speak','Speak'],['support','Pause / support'],['leave','Resolve / leave']]){const button=document.createElement('button');button.textContent=name;button.setAttribute('aria-pressed',String(group===id));button.onclick=()=>{battleGroup=id;battle();};tabs.append(button);}p.append(tabs);
      if(b.history.length){const d=document.createElement('details'),sum=document.createElement('summary');sum.textContent='Conversation so far';d.append(sum);for(const h of b.history){const row=document.createElement('p');row.className='battle-log';row.textContent=h.action+': '+h.text;d.append(row);}p.append(d);}
    },note:group==='support'?'Pausing costs two minutes. It does not advance the supervisor’s tactic.':group==='leave'?'Accepting €12 leaves €12 owed. Leaving recovers no wages. Neither choice is forced by stress.':'Goal: reduce objections to 0 for your €24. A larger number in a reply’s effect is better. Low energy? Eat a snack. High stress? Breathe. You choose whether to accept half or leave.',options:ids.map(id=>({label:(id===({stall:'evidence',blame:'boundary',offer:'negotiate'}[tell])?'★ ':'')+E.ACTIONS[id].name,hint:E.actionInfo(state,id).replace(/(\d+) resistance/,'−$1 objections'),disabled:!E.canAct(state,id),run:()=>playBattleAction(id)}))});
  }

  function journal(){
    if(E.Memories.current(state)&&!['intro','battle','ending'].includes(state.mode))return memoryJournal();
    if(['intro','battle','ending'].includes(state.mode))return;
    panel({kicker:'MENU / ARIS',title:'Your evening',mode:'journal',extra:p=>{
      const list=document.createElement('ol');list.className='journal-quests';for(const q of $('quests').children)list.append(q.cloneNode(true));p.append(list);
      const grid=document.createElement('div');grid.className='journal-grid';
      for(const [title,body]of [['IN YOUR BAG',(state.inventory.rota?'Thursday’s rota. ':'')+(state.inventory.groceries?'Dinner groceries. ':'')+state.inventory.snack+' sesame bar(s). '+state.inventory.ticket+' unused ticket(s). '+(E.validTicket(state)?'Active until '+clock(state.transit.validUntil)+'.':'No active ticket.')],['YOUR PEOPLE','Eleni: '+E.relation(state,'eleni')+'. Mina: '+E.relation(state,'mina')+'. Dimos: '+E.relation(state,'dimos')+'.'],['ENERGY / STRESS',state.energy+' / 100 energy · '+state.stress+' / 100 stress']]){
        const d=document.createElement('div'),k=document.createElement('div'),b=document.createElement('p');k.className='eyebrow';k.textContent=title;b.textContent=body;d.append(k,b);grid.append(d);
      }p.append(grid);
      const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Find a person or place';details.append(summary);
      const nav=document.createElement('div');nav.className='choice-list';for(const id of (state.room?E.places(state).map(p=>p.id):['home','mina','employer','shop','dimos','venue'])){const place=E.places(state).find(p=>p.id===id),b=document.createElement('button');b.className='choice';b.textContent=place.name;b.addEventListener('click',()=>{close();motion.go(E.path(state,place),place);line('ARIS','Walking to '+place.name.toLowerCase()+'.');});nav.append(b);}details.append(nav);p.append(details);
    },options:[{label:extraSlow?'Walking pace: Extra slow':'Walking pace: Calm',hint:'Tap to change',run:()=>{extraSlow=!extraSlow;try{localStorage.setItem('stereotype-zero-slow',String(extraSlow));}catch{}journal();}},{label:'Open neighborhood / Athens map',hint:'M',disabled:!!state.room,run:()=>map()},{label:state.room?'Back to the room':'Back to the street',hint:'B',run:close},{label:'Save evening',hint:'On this device',run:()=>save(true)},{label:'Load saved evening',disabled:!hasSave(),run:load}]});
  }
  function memoryJournal(){const q=E.Memories.current(state);panel({kicker:'MEMORIES / '+q.age,title:'This moment in the city',body:E.Memories.goal(state),portrait:q.avatar,mode:'journal',options:[{label:'Open the memory notebook',hint:Object.keys(state.memory.life.pages).length+' pages · '+Object.keys(state.memory.life.bag).length+' gathered items',run:notebook},...E.places(state).map(p=>({label:p.name,hint:state.memory.visited[q.id+':'+p.id]?'Visited':'Walk here',run:()=>{close();motion.go(E.path(state,p),p);}})),{label:extraSlow?'Walking pace: Extra slow':'Walking pace: Calm',run:()=>{extraSlow=!extraSlow;try{localStorage.setItem('stereotype-zero-slow',String(extraSlow));}catch{}memoryJournal();}},{label:'People around you · family record',run:familyBook},{label:'Save this memory',run:()=>save(true)},{label:'Back to the memory',run:close}]});}
  function walkTo(place){close();motion.go(E.path(state,place),place);line('ARIS','Walking to '+place.name.toLowerCase()+'.');}
  function map(view='Neighborhood'){if(state.room){toast('Step outside to use the city map');return;}if(['intro','battle','ending'].includes(state.mode))return;panel({kicker:'MAP / NORTH IS UP',title:'Find your way.',mode:'journal',className:'map-panel',extra:p=>window.CityMap.mount(p,state,walkTo,view),options:[{label:state.room?'Back to the room':'Back to the street',hint:'B',run:close}]});}
  function phone(){if(E.Memories.current(state))return;if(state.mode==='intro'||state.mode==='battle'||state.mode==='ending')return;panel({kicker:'SELECT / PHONE · 12% BATTERY',title:'Eleni · 1 unread',body:'“If you pass the market, get something we can actually cook. Also: tell me if you’re late.”',options:[{label:state.flags.phone?'Read Eleni’s reply':'Send an honest update',hint:state.flags.phone?'No extra time':'+ trust · −5 stress · 2 min',run:()=>response('Eleni · messages',E.phone(state))},{label:'Put the phone away',run:close}]});}
  function confirmEnd(where){const missing=!state.flags.delivered;panel({kicker:where==='gig'?'BASEMENT DOOR / THE FIRST BASS NOTE':'HOME / THE KITCHEN LIGHT',title:where==='gig'?'Go downstairs?':'Call it a night?',body:where==='gig'?(state.minutes>=1140?'The set has started. You can still go in.':'Soundcheck is almost done. You can wait inside until the set starts.'):'There is a chair at the table. Tonight can end here.',note:(missing?'Groceries have not been delivered. ':'')+(!state.flags.wages&&!state.flags.walkedAway?'Your wages are unresolved. ':'')+'This ends Chapter 01. Your choices will be reflected in the ending.',options:[{label:where==='gig'?'Go in. Hear the music.':'Stay with Eleni',hint:'End chapter',run:()=>{E.end(state,where);ending();}},{label:'There’s something I want to do first',run:close}]});}
  function ending(){audio.setScene('street');const e=state.ending;let body=e.where==='gig'?(e.late?'You slip in after the first song. Dimos sees you from behind the borrowed mixer. A nod. You are here.':'You wait through soundcheck. When Dimos plays your demo, the room goes quiet for a moment. Then someone starts moving.'):'You sit with Eleni. She closes her notes. For once, neither of you asks what comes next.';body+=' '+(e.delivered?'Dinner is taken care of.':state.inventory.groceries?'The grocery bag is still at your feet.':'Dinner still needs sorting.');body+=' '+(state.flags.settlement?'Half the wages arrived. The rest will wait.':state.flags.wages?'The wages arrived. Tomorrow has a little more room.':state.flags.walkedAway?'You left the wages behind for tonight.':'The missing wages remain missing.');if(state.topics['dimos:music']&&e.where==='gig')body+=' You remember what Dimos said: being scared is different from not wanting it.';if(state.topics['eleni:dream']&&e.where==='home')body+=' You talk about a room with a window that opens. A small dream, still yours.';panel({kicker:'CHAPTER 01 / END OF AN EVENING',title:e.where==='gig'?'A place in the room.':'A light left on.',body,mode:'ending',extra:p=>{const d=document.createElement('div');d.className='ending-stats';for(const s of [money(state.money)+' left',clock(state.minutes)+(e.where==='gig'&&state.minutes<1140?' arrival · set at 19:00':''),state.flags.delivered?'Dinner delivered':'Dinner unresolved',state.flags.attended?'Music heard':'A quiet evening']){const span=document.createElement('span');span.textContent=s;d.append(span);}p.append(d);},note:'This is a playable first chapter, not the whole city. Your next evening has yet to be written.',options:[{label:'Walk this evening again',hint:'New game',run:()=>{state=E.fresh();motion.sync();Art.resetCamera();audio.setScene('street');intro();}},{label:'Save this ending',hint:'On this device',run:save}]});line('ARIS · INNER VOICE','The city is still loud. You found a little room inside it.');}
  function save(notify=true){if(!state.flags.started){if(notify)toast('Start the evening first.');return;}try{localStorage.setItem('stereotype-zero-save',E.snapshot(state));$('save-status').textContent='Evening saved on this device.';if(notify)toast('Evening saved');}catch{if(notify)toast('Storage unavailable.');}}
  function load(){let loaded;storyShown=null;try{loaded=E.restore(localStorage.getItem('stereotype-zero-save'));}catch{}if(!loaded){$('save-status').textContent='No valid save found.';return;}state=loaded;motion.sync();Art.resetCamera();pendingInteraction=null;route=[];audio.setScene(state.mode==='battle'?'battle':'street');if(state.mode==='memory-battle')memoryEncounter();else if(state.mode==='battle')battle();else if(state.mode==='ending')ending();else{state.mode='explore';overlay.className='overlay';$('location-tag').hidden=false;canvas.focus({preventScroll:true});line(E.Memories.current(state)?'YOU':'ARIS · INNER VOICE',E.Memories.goal(state)||(state.room?'Back inside. The evening is where you left it.':'Back on the block. The evening is where you left it.'));}hud();$('save-status').textContent='Evening loaded.';}

  let extraSlow=false;try{extraSlow=localStorage.getItem('stereotype-zero-slow')==='true';}catch{}
  const keys=new Map();let stickPointer=null,stickStrength=0,typing=null,pendingInteraction=null,lastTime=0,toastTimer=null,tapStart=null,lastDoor='';
  const joystick=$('joystick'),knob=$('stick-knob');
  function releaseInput(){keys.clear();stickPointer=null;knob.style.transform='';motion.stop();}
  function finishTyping(){if(typing){typing.node.textContent=typing.text;typing=null;return true;}return false;}
  function toast(text){$('save-toast').textContent=text;$('save-toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('save-toast').classList.remove('show'),1700);}
  function nearby(){const p=E.nearest(state);const prompt=$('nearby-prompt');prompt.hidden=!p||state.mode!=='explore';if(p){prompt.querySelector('b').textContent=({home:'Enter home',mina:'Talk to Mina',dimos:'Talk to Dimos',employer:'Enter the stockroom',kiosk:'Visit the kiosk',shop:'Enter the market',bench:'Rest in the shade',metro:'Kato Patisia station',venue:'Enter the basement venue',bus:'Patision bus stop',north:'Toward Ano Patisia',south:'Toward the centre'})[p.id]||p.name;}const id=p?.id||'';if(id!==lastNearby){lastNearby=id;line(p?p.name.toUpperCase():E.Memories.current(state)?'YOU':'ARIS',p?'A to interact · tap to approach':E.Memories.goal(state)||'An evening in Kato Patisia.');}}
  function facePlace(p){const dx=p.x-state.x,dy=p.y-state.y;if(dx||dy)state.facing=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');}
  function confirm(){if(E.Opening.current(state)?.kind==='timed')return;if(finishTyping())return;if(state.mode==='explore')interact();else if(overlay.contains(document.activeElement)&&document.activeElement.matches('button'))document.activeElement.click();else overlay.querySelector('button:not(:disabled)')?.click();}
  function back(){if(E.Opening.current(state)?.kind==='timed')return;if(E.Opening.current(state)?.kind==='dialogue'){confirm();return;}finishTyping();if(state.mode==='memory-battle'){if(state.memory.life.active?.result==='won'){E.finishMemoryEncounter(state);close();}else line('ENCOUNTER','Choose Step away to leave this moment.');}else if(state.mode==='battle'){if(state.battle.result)overlay.querySelector('button')?.click();else line('ARIS','Choose Walk away to leave this encounter.');}else if(state.mode==='explore'&&E.Memories.current(state)){journal();}else if(state.mode==='explore'&&state.room){const exit=E.places(state).find(p=>p.id==='exit');motion.go(E.path(state,exit),exit);}else close();}
  function directionInput(dir){if(state.mode!=='explore')return;pendingInteraction=null;motion.hold(dir);}
  function stickMove(e){const r=joystick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,radius=r.width*.32,length=Math.hypot(dx,dy),factor=length>radius?radius/length:1;knob.style.transform='translate('+Math.round(dx*factor)+'px,'+Math.round(dy*factor)+'px)';const input=window.CityMotion.stick(dx,dy,r.width,motion.held);stickStrength=input.strength;if(!input.dir){motion.release();return;}directionInput(input.dir);}
  joystick.addEventListener('pointerdown',e=>{if(state.mode!=='explore'||stickPointer!==null)return;e.preventDefault();stickPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);stickMove(e);});
  joystick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer){e.preventDefault();stickMove(e);}});
  function releaseStick(e){if(e.pointerId!==stickPointer)return;stickPointer=null;knob.style.transform='';motion.release();}
  for(const type of ['pointerup','pointercancel','lostpointercapture'])joystick.addEventListener(type,releaseStick);
  for(const b of document.querySelectorAll('[data-move]'))b.addEventListener('click',e=>{if(e.detail===0&&state.mode==='explore')motion.tap(b.dataset.move);});
  const directions={arrowup:'up',arrowdown:'down',arrowleft:'left',arrowright:'right',w:'up',s:'down',a:'left',d:'right'};
  document.addEventListener('keydown',e=>{
    if(e.ctrlKey||e.metaKey||e.altKey)return;const key=e.key.toLowerCase();
    if(directions[key]){
      e.preventDefault();if(state.mode==='explore'){if(!keys.has(key)){keys.set(key,directions[key]);directionInput(directions[key]);}}
      else if(!e.repeat){finishTyping();const buttons=[...overlay.querySelectorAll('button:not(:disabled)')],i=buttons.indexOf(document.activeElement),delta=['up','left'].includes(directions[key])?-1:1;buttons[(i+delta+buttons.length)%buttons.length]?.focus();}
      return;
    }
    if(['z','enter',' '].includes(key)){if(document.activeElement.matches('button')&&!overlay.contains(document.activeElement)&&key!=='z')return;e.preventDefault();if(!e.repeat)confirm();}
    else if(['escape','x','backspace'].includes(key)){e.preventDefault();if(!e.repeat)back();}
    else if(key==='j'){e.preventDefault();if(!e.repeat)journal();}
    else if(key==='p'){e.preventDefault();if(!e.repeat)phone();}
    else if(key==='m'){e.preventDefault();if(!e.repeat)map();}
  });
  document.addEventListener('keyup',e=>{const key=e.key.toLowerCase();if(keys.delete(key)){const remaining=[...keys.values()];if(remaining.length&&state.mode==='explore')motion.hold(remaining[remaining.length-1]);else motion.release();}});
  window.addEventListener('blur',releaseInput);
  canvas.addEventListener('pointerdown',e=>{if(state.mode!=='explore')return;tapStart={x:e.clientX,y:e.clientY,id:e.pointerId};canvas.setPointerCapture(e.pointerId);});
  canvas.addEventListener('pointercancel',()=>{tapStart=null;});
  canvas.addEventListener('pointerup',e=>{
    if(!tapStart||e.pointerId!==tapStart.id)return;const tap=tapStart;tapStart=null;if(Math.hypot(e.clientX-tap.x,e.clientY-tap.y)>14||state.mode!=='explore')return;
    const bounds=canvas.getBoundingClientRect(),wx=(e.clientX-bounds.left)/bounds.width*canvas.width+Art.camera.x,wy=(e.clientY-bounds.top)/bounds.height*canvas.height+Art.camera.y;
    const x=wx/Art.T,y=wy/Art.T,p=E.places(state).reduce((best,p)=>Math.hypot(p.x+.5-x,p.y+.2-y)<(best?Math.hypot(best.x+.5-x,best.y+.2-y):Infinity)?p:best,null);
    pendingInteraction=null;releaseInput();
    if(p&&Math.hypot(p.x+.5-x,p.y+.2-y)<1.4){if(Math.abs(state.x-p.x)+Math.abs(state.y-p.y)<=2)interact(p);else{motion.go(E.path(state,p),p);line('ARIS','Walking to '+p.name.toLowerCase()+'.');}}
    else{const target={x:Math.floor(x),y:Math.floor(y)};if(E.walkable(target.x,target.y,state))motion.go(E.path(state,target,0));}
  });
  overlay.addEventListener('pointerdown',e=>{if(!e.target.closest('button'))finishTyping();});
  $('action').onclick=confirm;$('interact').onclick=()=>interact();$('back').onclick=back;$('journal').onclick=journal;$('map').onclick=()=>map();$('phone').onclick=phone;$('save').onclick=save;$('load').onclick=load;
  $('sound').onclick=async()=>{try{const on=await audio.toggle();$('sound').setAttribute('aria-pressed',String(on));$('sound').setAttribute('aria-label',on?'Disable music':'Enable music');toast(on?'Music on':'Music off');}catch{toast('Audio unavailable.');}};
  function resize(){const b=$('world').getBoundingClientRect(),scale=b.width<560?2:3;canvas.width=Math.max(120,Math.floor(b.width/scale));canvas.height=Math.max(100,Math.floor(b.height/scale));canvas.style.width=canvas.width*scale+'px';canvas.style.height=canvas.height*scale+'px';}
  new ResizeObserver(resize).observe($('world'));resize();
  function loop(t){
    const dt=lastTime?Math.min(100,t-lastTime):16;lastTime=t;driveOpening(dt);
    motion.duration=(state.room?520:480)+(extraSlow?140:0)+(stickPointer!==null?Math.round((1-stickStrength)*150):0);
    const arrived=motion.update(dt);if(arrived&&state.mode==='explore'){if(arrived.doorCross)finishDoor(E.crossDoor(state,arrived.doorCross));else interact(arrived);}
    if(!motion.moving&&state.mode==='explore'){const door=E.doors(state).find(p=>p.x===state.x&&p.y===state.y&&p.facing===state.facing),key=door?(state.room||'street')+':'+door.id:'';if(key&&key!==lastDoor){lastDoor=key;finishDoor(E.crossDoor(state,door));}else if(!key)lastDoor='';}
    E.updateActors(state,dt,motion);
    if(pendingInteraction&&!motion.moving&&state.mode==='explore'){const p=pendingInteraction;pendingInteraction=null;interact(p);}
    if(typing){typing.shown+=dt*.09;typing.node.textContent=typing.text.slice(0,Math.floor(typing.shown));if(typing.shown>=typing.text.length)typing=null;}
    nearby();audio.setScene(window.CityScore.sceneFor(state));Art.render(ctx,state,motion,t,dt);const playScene=overlay.querySelector('.play-scene');if(playScene)Art.playScene(playScene.getContext('2d'),state,t);const lifeScene=overlay.querySelector('.life-encounter');if(lifeScene)drawMemoryEncounter(lifeScene.getContext('2d'),t);const scene=overlay.querySelector('.encounter-scene');if(scene)Art.encounter(scene.getContext('2d'),state,t);requestAnimationFrame(loop);
  }
  function pauseGame(){releaseInput();pendingInteraction=null;if(state.flags.started)save(false);if(audio.context)audio.context.suspend().catch(()=>{});}
  function resumeGame(){if(audio.context&&audio.enabled){audio.next=audio.context.currentTime+.05;audio.context.resume().catch(()=>{});}}
  window.addEventListener('stereotype-zero-pause',pauseGame);window.addEventListener('stereotype-zero-resume',resumeGame);
  document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseGame();else resumeGame();});window.addEventListener('pagehide',pauseGame);
  setInterval(()=>{if(state.flags.started&&!document.hidden)save(false);},15000);
  Art.ready.then(()=>{$('boot').hidden=true;Art.face($('portrait').getContext('2d'),'memory-child',64);hud();if(hasSave())intro();else{E.startMemories(state);motion.sync();Art.resetCamera();memoryCard();}requestAnimationFrame(loop);}).catch(()=>{$('boot').querySelector('span').textContent='Art could not load. Please reload or reinstall.';});
})();
